>
> int main(int argc, char **argv)
> {
>         int fd = open_amdgpu_render(argc > 1 ? argv[1] : NULL);
>         if (fd < 0)
>                 return 1;
>
>         /* anonymous, private, page-aligned region for the userptr */
>         void *buf = mmap(NULL, BUF_SIZE, PROT_READ | PROT_WRITE,
>                          MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
>         if (buf == MAP_FAILED) {
>                 perror("mmap");
>                 return 1;
>         }
>         memset(buf, 0xa5, BUF_SIZE); /* fault every page in */
>
>         /* REGISTER installs the mmu_interval_notifier (amdgpu_hmm_register());
>          * VALIDATE additionally faults the pages via hmm_range_fault() and
>          * binds them into GTT. ANONONLY matches our MAP_ANONYMOUS region. */
>         struct drm_amdgpu_gem_userptr up = {
>                 .addr  = (uint64_t)(uintptr_t)buf,
>                 .size  = BUF_SIZE,
>                 .flags = AMDGPU_GEM_USERPTR_ANONONLY |
>                          AMDGPU_GEM_USERPTR_REGISTER |
>                          AMDGPU_GEM_USERPTR_VALIDATE,
>         };
>         if (ioctl(fd, DRM_IOCTL_AMDGPU_GEM_USERPTR, &up)) {
>                 perror("GEM_USERPTR (VALIDATE)");
>                 /* retry without VALIDATE: the notifier is still registered, the
>                  * pages are present from the memset, MADV_PAGEOUT still works */
>                 up.flags = AMDGPU_GEM_USERPTR_ANONONLY |
>                            AMDGPU_GEM_USERPTR_REGISTER;
>                 if (ioctl(fd, DRM_IOCTL_AMDGPU_GEM_USERPTR, &up)) {
>                         perror("GEM_USERPTR (REGISTER)");
>                         return 1;
>                 }
>         }
>         fprintf(stderr, "userptr handle=%u, interval notifier armed over %p..%p\n",
>                 up.handle, buf, (char *)buf + BUF_SIZE);
>
>         /* Force synchronous reclaim of the notifier-covered range. MADV_PAGEOUT
>          * runs shrink_folio_list()->try_to_unmap()->invalidate_range_start()
>          * with fs_reclaim held in THIS thread, so amdgpu_hmm_invalidate_gfx()
>          * takes notifier_lock under fs_reclaim and lockdep closes the cycle.
>          *
>          * A few iterations (re-touching in between) cover the race where pages
>          * are already paged out on the first pass. */
>         for (int it = 0; it < 8; it++) {
>                 if (madvise(buf, BUF_SIZE, MADV_PAGEOUT))
>                         perror("madvise(MADV_PAGEOUT)");
>                 usleep(50 * 1000);
>                 memset(buf, 0xa5, BUF_SIZE); /* fault back in for the next pass */
>         }
>
>         fprintf(stderr,
>                 "done: check dmesg for "
>                 "\"possible circular locking dependency\" / amdgpu_hmm_invalidate_gfx\n");
>
>         munmap(buf, BUF_SIZE);
>         close(fd);
>         return 0;
> }

On 6/22/26 9:36 AM, Gao Xiang wrote:
> EROFS over fscache was introduced to provide image lazy pulling
> functionality. After the feature landed, the fscache subsystem made
> netfs a new hard dependency, which is unexpected for a local filesystem
> and has an kernel-defined caching hierarchy which could be inflexible
> compared to the fanotify pre-content hooks. Therefore, this feature has
> been deprecated for almost two years.
> 
> As EROFS file-backed mounts and fanotify pre-content hooks both upstream
> for a while and already providing equivalent functionality (erofs-utils
> has supported fanotify pre-content hooks), let's remove the fscache
> backend now.
> 
> The main application of this feature is Nydus [1], and they plan to move
> to use fanotify pre-content hooks in the near future too.
> 
> I hope this patch can be merged into Linux 7.2, which is also motivated
> by newly found implementation issues [2][3] that are not worth
> investigating given the deprecation and limited development resources.
> The associated fscache/cachefiles cleanup patch will follow separately
> through the vfs tree (netfs) later: it seems fine since the codebase is
> isolated by CONFIG_CACHEFILES_ONDEMAND.
> 
> [1] https://github.com/dragonflyoss/nydus/blob/v2.1.0/docs/nydus-fscache.md
> [2] https://github.com/dragonflyoss/nydus/pull/1824
> [3] https://lore.kernel.org/r/20260619135800.1594811-1-michael.bommarito@gmail.com
> Signed-off-by: Gao Xiang <hsiangkao@linux.alibaba.com>


Acked-by: Jingbo Xu <jefflexu@linux.alibaba.com>


