index 1f9297e9776a..8ea7d4b9f0c0 100644
--- a/lib/string.c
+++ b/lib/string.c
@@ -837,7 +837,8 @@ void *memchr_inv(const void *start, int c, size_t bytes)
 {
 	u8 value = c;
 	u64 value64;
-	unsigned int words, prefix;
+	size_t words;
+	unsigned int prefix;
 
 	if (bytes <= 16)
 		return check_bytes8(start, value, bytes);
